instrument_url = "https://api.kite.trade/instruments"
# Retrieve the CSV dump
response = requests.get(instrument_url)
if response.status_code == 200:
    # Convert the response content to a string
    content_str = response.text
    instruments_df = pd.read_csv(StringIO(content_str))
    instruments_df = instruments_df[instruments_df['exchange'] == 'NSE']
    instruments_df.dropna(subset=["name"], inplace=True)
    indices_stocks = instruments_df[instruments_df['segment'] == 'INDICES']
    nse_top_stocks = instruments_df[(instruments_df['segment'] == 'NSE') & (instruments_df['tradingsymbol'].isin(top_stocks))]
    final_df = pd.concat([indices_stocks, nse_top_stocks], ignore_index=True)
    final_df = final_df.drop(columns=['expiry'])

    print("All zerodha stocks Loaded!!!!!" + str(len(final_df)))

    return final_df
else:
    print("Failed to retrieve data. Status code:", response.status_code)
    return None


